import pyomo.environ as pyo

DATA = {
    "antibiotics_available": 35000,
    "first_dose": {
        "antibiotics": 30,
        "gelatine": 20,
        "index": "F",
    },
    "second_dose": {
        "antibiotics": 65,
        "gelatine": 60,
        "index": "S",
    },
    "min_second_dose": 40,
    "strict_gap": 1,
}


def build_model(data=None):
    d = data or DATA

    first = d["first_dose"]["index"]
    second = d["second_dose"]["index"]

    model = pyo.ConcreteModel()

    model.P = pyo.Set(initialize=[first, second])

    gel = {
        first: d["first_dose"]["gelatine"],
        second: d["second_dose"]["gelatine"],
    }
    abx = {
        first: d["first_dose"]["antibiotics"],
        second: d["second_dose"]["antibiotics"],
    }

    model.gel_use = pyo.Param(model.P, initialize=gel, within=pyo.NonNegativeReals)
    model.abx_use = pyo.Param(model.P, initialize=abx, within=pyo.NonNegativeReals)

    model.x = pyo.Var(model.P, within=pyo.NonNegativeIntegers, bounds=(0, None))

    model.obj = pyo.Objective(
        expr=sum(model.gel_use[p] * model.x[p] for p in model.P),
        sense=pyo.minimize,
    )

    def antibiotics_rule(m):
        return sum(m.abx_use[p] * m.x[p] for p in m.P) <= d["antibiotics_available"]

    model.antibiotics = pyo.Constraint(rule=antibiotics_rule)

    def more_first_rule(m):
        return m.x[first] >= m.x[second] + d["strict_gap"]

    model.more_first = pyo.Constraint(rule=more_first_rule)

    def min_second_rule(m):
        return m.x[second] >= d["min_second_dose"]

    model.min_second = pyo.Constraint(rule=min_second_rule)

    return model


